import 'dart:convert';

import 'api_model.dart';
import 'doc_renderer.dart';

/// The documented types as JSON, for the website (`website/src/data/api.json`).
///
/// [pages] tells the documentation file of each type (the descriptions link
/// relative to it), and [anchors] where each type is documented.
String apiJson(
  Iterable<ApiType> types,
  Map<String, String> pages,
  Map<String, String> anchors,
) {
  final sorted = types.toList()..sort((a, b) => a.name.compareTo(b.name));
  final json = {
    '//': 'Generated by tool/api_docs from the dartdoc, run `make docs`.',
    for (final type in sorted)
      type.name: _type(type, pages[type.name]!, anchors),
  };
  return '${const JsonEncoder.withIndent('  ').convert(json)}\n';
}

Map<String, Object?> _type(
  ApiType type,
  String page,
  Map<String, String> anchors,
) {
  final renderer = DocRenderer(type, page, anchors);
  final parent = type.inheritsFrom;
  return {
    'page': page,
    'mode': type.mode.name,
    if (parent != null)
      'inheritsFrom': {'name': parent, 'link': renderer.docsLink(parent)},
    'members': [
      for (final member in type.members)
        {
          'name': member.name,
          if (member.type != null) 'type': member.type,
          if (member.defaultValue != null) 'defaultValue': member.defaultValue,
          if (member.isRequired) 'required': true,
          if (member.deprecationMessage != null)
            'deprecated': member.deprecationMessage,
          'description': renderer.markdown(member.doc),
        },
    ],
  };
}
